from collections import Counter

def solve(data):
    s = data['s']
    t = data['t']

    if not t:
        return ''

    char_count_t = Counter(t)
    char_count_s = Counter(s)

    min_length = len(s)
    result = ""

    for i in range(len(s)):
        for j in range(i, len(s)):
            current_char_count_s = char_count_s.copy()
            for k in range(i, j + 1):
                if s[k] in char_count_t:
                    current_char_count_s[s[k]] -= 1
                    if current_char_count_s[s[k]] < 0:
                        break
            if all(current_char_count_s[char] >= 0 for char in char_count_t):
                if j - i + 1 < min_length:
                    min_length = j - i + 1
                    result = s[i:j+1]

    return result
